info.description:
/* Custom CSS for GitHub Contribution Graph - Halloween Theme */
rect[class*="ContributionCalendar-day"] {
    fill: #1c1c1c !important; /* Dark black for zero contributions */
}
rect[data-level="1"] {
    fill: #5a5a5a !important; /* Dark gray for low contributions */
}
rect[data-level="2"] {
    fill: #8e6e53 !important; /* Brownish-orange for medium contributions */
}
rect[data-level="3"] {
    fill: #d35400 !important; /* Orange for high contributions */
}
rect[data-level="4"] {
    fill: #ff7518 !important; /* Bright orange for maximum contributions */
}

